mapper.select:
# TODO: Not thoroughly tested, especially the facilities part and the date-time part
        SELECT * FROM meeting_rooms LEFT JOIN reservations ON meeting_rooms.room_id = reservations.room_id
        WHERE

                meeting_rooms.capacity_min <= #{attendeesCount} AND meeting_rooms.capacity_max >= #{attendeesCount}


                AND meeting_rooms.building = #{building}


                AND meeting_rooms.floor = #{floor}



                    AND meeting_rooms.facilities @> '{"projector": #{facilities.getProjector()}}'


                    AND meeting_rooms.facilities->>'whiteboard'::int >= #{facilities.getWhiteboard()}


                    AND meeting_rooms.facilities->>'power_sockets'::int >= #{facilities.getPowerSockets()}


                    AND meeting_rooms.facilities @> '{"coffee_break": #{facilities.getCoffeeBreak()}}'



                        meeting_rooms.facilities @> '{"special_notes": #{note}}'




                AND reservations.end_time <= #{startTime}


                AND reservations.start_time >= #{endTime}
